SELECT visible.*
FROM (

) visible
WHERE 1 = 1

    AND visible.workplace_id = #{workplaceId}


    AND visible.doc_type = #{docType}

ORDER BY visible.created_at DESC,
         visible.document_id DESC,
         visible.work_case_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM (

) visible
WHERE 1 = 1

    AND visible.workplace_id = #{workplaceId}


    AND visible.doc_type = #{docType}

SELECT COUNT(*) > 0
FROM documents d
WHERE d.id = #{documentId}
  AND d.owner_user_id = #{ownerUserId}
  AND d.document_type = 'HEALTH_CERTIFICATE'
  AND d.status = 'ACTIVE'

SELECT d.expires_on
FROM documents d
WHERE d.id = #{documentId}
  AND d.owner_user_id = #{ownerUserId}
  AND d.document_type = 'HEALTH_CERTIFICATE'
  AND d.status = 'ACTIVE'
